-- xRewind 1.1.1's SQLite database, as its Schema.STEPS (schema 1) made it and its writer filled it:
-- a stone Steve broke, a chest #tnt blew up (with what it held), diamonds Steve took, his join, a sign.
-- Times are seconds since 2026-01-01 UTC; 13046400 is 2026-06-01.
CREATE TABLE xrewind_meta (name VARCHAR(64) PRIMARY KEY, value VARCHAR(255) NOT NULL)
INSERT INTO xrewind_meta (name, value) VALUES ('schema', '1')
CREATE TABLE xrewind_user (id INTEGER PRIMARY KEY, uuid_most BIGINT, uuid_least BIGINT, name VARCHAR(64) NOT NULL)
CREATE TABLE xrewind_world (id INTEGER PRIMARY KEY, name VARCHAR(255) NOT NULL)
CREATE TABLE xrewind_state (id INTEGER PRIMARY KEY, data TEXT NOT NULL)
CREATE TABLE xrewind_item (id INTEGER PRIMARY KEY, hash BIGINT NOT NULL, data BLOB NOT NULL)
CREATE TABLE xrewind_block (id INTEGER PRIMARY KEY, time INT NOT NULL, user INT NOT NULL, world SMALLINT NOT NULL, x INT NOT NULL, y SMALLINT NOT NULL, z INT NOT NULL, action TINYINT NOT NULL, old_state INT NOT NULL, new_state INT NOT NULL, extra INT, rolled_back TINYINT NOT NULL DEFAULT 0)
CREATE INDEX xrewind_block_place ON xrewind_block (world, x, z, time)
CREATE INDEX xrewind_block_user ON xrewind_block (user, time)
CREATE INDEX xrewind_block_time ON xrewind_block (time)
CREATE TABLE xrewind_container (id INTEGER PRIMARY KEY, time INT NOT NULL, user INT NOT NULL, world SMALLINT NOT NULL, x INT NOT NULL, y SMALLINT NOT NULL, z INT NOT NULL, action TINYINT NOT NULL, material INT NOT NULL, item INT NOT NULL, amount INT NOT NULL, rolled_back TINYINT NOT NULL DEFAULT 0)
CREATE INDEX xrewind_container_place ON xrewind_container (world, x, z, time)
CREATE INDEX xrewind_container_user ON xrewind_container (user, time)
CREATE INDEX xrewind_container_time ON xrewind_container (time)
CREATE TABLE xrewind_entity (id INTEGER PRIMARY KEY, time INT NOT NULL, user INT NOT NULL, world SMALLINT NOT NULL, x INT NOT NULL, y SMALLINT NOT NULL, z INT NOT NULL, action TINYINT NOT NULL, type INT NOT NULL, extra INT, rolled_back TINYINT NOT NULL DEFAULT 0)
CREATE INDEX xrewind_entity_place ON xrewind_entity (world, x, z, time)
CREATE INDEX xrewind_entity_user ON xrewind_entity (user, time)
CREATE INDEX xrewind_entity_time ON xrewind_entity (time)
CREATE TABLE xrewind_text (id INTEGER PRIMARY KEY, time INT NOT NULL, user INT NOT NULL, world SMALLINT NOT NULL, x INT NOT NULL, y SMALLINT NOT NULL, z INT NOT NULL, kind TINYINT NOT NULL, message TEXT NOT NULL)
CREATE INDEX xrewind_text_user ON xrewind_text (user, time)
CREATE INDEX xrewind_text_time ON xrewind_text (time)
CREATE TABLE xrewind_session (id INTEGER PRIMARY KEY, time INT NOT NULL, user INT NOT NULL, world SMALLINT NOT NULL, x INT NOT NULL, y SMALLINT NOT NULL, z INT NOT NULL, action TINYINT NOT NULL)
CREATE INDEX xrewind_session_user ON xrewind_session (user, time)
CREATE INDEX xrewind_session_time ON xrewind_session (time)
